{"path":"/workspace/src/store.js","content":"import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

const EMPTY = { books: [] };

export function createStore(filePath) {
  let chain = Promise.resolve();

  async function read() {
    let raw;
    try {
      raw = await readFile(filePath, 'utf8');
    } catch (error) {
      if (error && error.code === 'ENOENT') return clone(EMPTY);
      throw error;
    }
    if (!raw.trim()) return clone(EMPTY);
    const data = JSON.parse(raw);
    if (!data || typeof data !== 'object' || !Array.isArray(data.books)) {
      throw new Error(`Invalid books file: ${filePath}`);
    }
    return data;
  }

  async function write(data) {
    await mkdir(dirname(filePath), { recursive: true });
    const tmp = `${filePath}.${process.pid}.tmp`;
    await writeFile(tmp, `${JSON.stringify(data, null, 2)}\n`, 'utf8');
    await rename(tmp, filePath);
  }

  function update(mutator) {
    const run = chain.then(async () => {
      const current = await read();
      const next = await mutator(current);
      if (!next || !Array.isArray(next.books)) {
        throw new Error('Store update must return a books array');
      }
      await write(next);
      return next;
    });
    chain = run.then(
      () => {},
      () => {},
    );
    return run;
  }

  return { filePath, read, update };
}

function clone(value) {
  return structuredClone(value);
}
"}

{"path":"/workspace/src/books.js","content":"import { randomBytes } from 'node:crypto';

const TITLE_MAX = 200;
const AUTHOR_MAX = 200;
const NOTES_MAX = 5000;

export function validateBookInput(input) {
  const title = String(input?.title ?? '').trim();
  const author = String(input?.author ?? '').trim();
  const notes = String(input?.notes ?? '').trim();
  const values = { title, author, notes };
  if (!title || !author) {
    return { error: 'Title and author are required.', values };
  }
  if (title.length > TITLE_MAX || author.length > AUTHOR_MAX) {
    return { error: 'Title and author must be 200 characters or fewer.', values };
  }
  if (notes.length > NOTES_MAX) {
    return { error: 'Notes must be 5000 characters or fewer.', values };
  }
  return { value: values, values };
}

export function addBook(data, input, now = new Date()) {
  const book = {
    id: uniqueId(data.books || []),
    title: input.title,
    author: input.author,
    notes: input.notes,
    status: 'reading',
    createdAt: now.toISOString(),
    finishedAt: null,
  };
  return { books: [book, ...(data.books || [])], book };
}

export function finishBook(data, id, now = new Date()) {
  const books = (data.books || []).map((book) => ({ ...book }));
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return null;
  if (books[index].status !== 'finished') {
    books[index] = {
      ...books[index],
      status: 'finished',
      finishedAt: now.toISOString(),
    };
  }
  return { books, book: books[index] };
}

export function findBook(data, id) {
  return (data.books || []).find((book) => book.id === id) || null;
}

export function splitBooks(data) {
  const books = data?.books || [];
  const reading = books
    .filter((book) => book && book.status !== 'finished')
    .sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')));
  const finished = books
    .filter((book) => book && book.status === 'finished')
    .sort((a, b) => String(b.finishedAt || '').localeCompare(String(a.finishedAt || '')));
  return { reading, finished };
}

export function isBookId(id) {
  return typeof id === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(id);
}

function uniqueId(books) {
  const used = new Set(books.map((book) => book.id));
  let id = '';
  do {
    id = randomBytes(4).toString('hex');
  } while (used.has(id));
  return id;
}
