{"path":"/workspace/src/render.js","content":"export function renderHome({ reading, finished, error = '', values = {} }) {
  const form = values || {};
  return layout({
    title: 'Books',
    body: `
      ${header()}
      <div class="lists">
        ${catalog('reading', 'Currently reading', reading, {
          empty: 'Nothing in progress.',
          showFinish: true,
        })}
        ${catalog('finished', 'Finished', finished, {
          empty: 'No finished books yet.',
          showFinish: false,
        })}
      </div>
      <section class="add" id="add-book">
        <h2>Add a book</h2>
        ${error ? `<p class="error" role="alert">${escapeHtml(error)}</p>` : ''}
        <form method="post" action="/books">
          <label for="title">Title</label>
          <input id="title" name="title" type="text" required maxlength="200" value="${escapeHtml(form.title || '')}">
          <label for="author">Author</label>
          <input id="author" name="author" type="text" required maxlength="200" value="${escapeHtml(form.author || '')}">
          <label for="notes">Notes</label>
          <textarea id="notes" name="notes" maxlength="5000">${escapeHtml(form.notes || '')}</textarea>
          <button class="primary" type="submit">Add book</button>
        </form>
      </section>
    `,
  });
}

export function renderBook(book, { shareUrl }) {
  const status = book.status === 'finished' ? 'Finished' : 'Currently reading';
  const notes = String(book.notes || '');
  const path = `/books/${book.id}`;
  return layout({
    title: `${book.title} — Books`,
    body: `
      ${header()}
      <article class="book">
        <p class="back"><a href="/">All books</a></p>
        <p class="status ${book.status === 'finished' ? 'finished' : 'reading'}">${status}</p>
        <h1>${escapeHtml(book.title)}</h1>
        <p class="by">by ${escapeHtml(book.author)}</p>
        <h2>Notes</h2>
        ${
          notes
            ? `<p class="notes">${escapeHtml(notes)}</p>`
            : '<p class="empty">No notes yet.</p>'
        }
        ${
          book.status === 'finished'
            ? ''
            : `<form class="finish" method="post" action="${path}/finish">
                <input type="hidden" name="next" value="${path}">
                <button type="submit">Mark as finished</button>
              </form>`
        }
        <section class="share">
          <h2>Share</h2>
          <p>Send this link to someone.</p>
          <p><a href="${path}">${escapeHtml(shareUrl)}</a></p>
        </section>
      </article>
    `,
  });
}

export function renderNotFound(message = 'Book not found') {
  return layout({
    title: 'Not found — Books',
    body: `
      ${header()}
      <article class="missing">
        <h1>${escapeHtml(message)}</h1>
        <p class="back"><a href="/">All books</a></p>
      </article>
    `,
  });
}

function header() {
  return `
    <header class="site">
      <h1><a class="brand" href="/">Books</a></h1>
      <p><a href="/#add-book">Add a book</a></p>
    </header>
  `;
}

function catalog(id, label, books, { empty, showFinish }) {
  const items = books.length
    ? `<ul class="catalog">${books.map((book) => catalogItem(book, showFinish)).join('')}</ul>`
    : `<p class="empty">${empty}</p>`;
  return `
    <section id="${id}">
      <h2 id="${id}-heading">${label}</h2>
      ${items}
    </section>
  `;
}

function catalogItem(book, showFinish) {
  const path = `/books/${book.id}`;
  const finished = book.finishedAt ? `<span class="meta">${escapeHtml(formatDate(book.finishedAt))}</span>` : '';
  const action = showFinish
    ? `<form class="finish" method="post" action="${path}/finish">
        <input type="hidden" name="next" value="/">
        <button type="submit" aria-label="Mark ${escapeHtml(book.title)} as finished">Mark as finished</button>
      </form>`
    : finished;
  return `
    <li>
      <a class="title" href="${path}">${escapeHtml(book.title)}</a>
      <span class="author">${escapeHtml(book.author)}</span>
      ${action}
    </li>
  `;
}

function formatDate(iso) {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return '';
  return new Intl.DateTimeFormat('en', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    timeZone: 'UTC',
  }).format(date);
}

