{"path":"/workspace/src/app.js","content":"import { addBook, findBook, finishBook, isBookId, splitBooks, validateBookInput } from './books.js';
import { renderBook, renderHome, renderNotFound } from './render.js';

export function createApp(store) {
  return async function handle(request) {
    const url = new URL(request.url || '/', 'http://localhost');
    const path = normalizePath(url.pathname);
    const method = String(request.method || 'GET').toUpperCase();

    if (path === '/favicon.ico') return empty(204);

    if (path === '/') {
      if (method !== 'GET' && method !== 'HEAD') return text(405, 'Method not allowed');
      const data = await store.read();
      return html(200, renderHome(splitBooks(data)));
    }

    if (path === '/books') {
      if (method === 'GET' || method === 'HEAD') return redirect('/');
      if (method !== 'POST') return text(405, 'Method not allowed');
      const fields = parseForm(request.body);
      const parsed = validateBookInput(fields);
      if (parsed.error) {
        const data = await store.read();
        return html(400, renderHome({ ...splitBooks(data), error: parsed.error, values: parsed.values }));
      }
      let book;
      await store.update((data) => {
        const result = addBook(data, parsed.value);
        book = result.book;
        return { books: result.books };
      });
      return redirect(`/books/${book.id}`);
    }

    const finish = path.match(/^\/books\/([^/]+)\/finish$/);
    if (finish) {
      const id = decodeId(finish[1]);
      if (!id) return html(404, renderNotFound());
      if (method !== 'POST') return text(405, 'Method not allowed');
      const fields = parseForm(request.body);
      let found = false;
      await store.update((data) => {
        const result = finishBook(data, id);
        if (!result) return data;
        found = true;
        return { books: result.books };
      });
      if (!found) return html(404, renderNotFound());
      return redirect(safeNext(fields.next, id));
    }

    const detail = path.match(/^\/books\/([^/]+)$/);
    if (detail) {
      const id = decodeId(detail[1]);
      if (!id) return html(404, renderNotFound());
      if (method !== 'GET' && method !== 'HEAD') return text(405, 'Method not allowed');
      const book = findBook(await store.read(), id);
      if (!book) return html(404, renderNotFound());
      return html(200, renderBook(book, { shareUrl: absoluteUrl(request, `/books/${book.id}`) }));
    }

    return html(404, renderNotFound('Page not found'));
  };
}

function normalizePath(pathname) {
  const trimmed = pathname.replace(/\/+$/, '');
  return trimmed || '/';
}

function decodeId(raw) {
  try {
    const id = decodeURIComponent(raw);
    return isBookId(id) ? id : null;
  } catch {
    return null;
  }
}

function parseForm(body) {
  const params = new URLSearchParams(typeof body === 'string' ? body : '');
  return {
    title: params.get('title') ?? '',
    author: params.get('author') ?? '',
    notes: params.get('notes') ?? '',
    next: params.get('next') ?? '',
  };
}

function safeNext(value, id) {
  if (value === '/') return '/';
  if (value === `/books/${id}`) return value;
  return `/books/${id}`;
}

function absoluteUrl(request, path) {
  const headers = request.headers || {};
  const host = headers.host;
  if (!host || /[\s/]/.test(host)) return path;
  const forwarded = headers['x-forwarded-proto'];
  const proto = forwarded === 'https' ? 'https' : 'http';
  return `${proto}://${host}${path}`;
}

function html(status, body) {
  return {
    status,
    headers: {
      'content-type': 'text/html; charset=utf-8',
      'cache-control': 'no-store',
    },
    body,
  };
}

function text(status, body) {
  return {
    status,
    headers: { 'content-type': 'text/plain; charset=utf-8' },
    body,
  };
}

function redirect(location) {
  return {
    status: 303,
    headers: {
      location,
      'content-type': 'text/plain; charset=utf-8',
    },
    body: `Redirecting to ${location}\n`,
  };
}

function empty(status) {
  return { status, headers: {}, body: '' };
}
"}

{"path":"/workspace/server.js","content":"import { createServer } from 'node:http';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { createApp } from './src/app.js';
import { createStore } from './src/store.js';

const root = dirname(fileURLToPath(import.meta.url));
const BODY_LIMIT = 100_000;

export function startServer({ port = Number(process.env.PORT) || 3000, host = '0.0.0.0', dataFile } = {}) {
  const file = dataFile || (process.env.BOOKS_FILE ? resolve(process.env.BOOKS_FILE) : join(root, 'data', 'books.json'));
  const store = createStore(file);
  const app = createApp(store);
  const server = createServer(async (req, res) => {
    try {
      const body = await readBody(req);
      const result = await app({
        method: req.method,
        url: req.url,
        headers: req.headers,
        body,
      });
      res.writeHead(result.status, result.headers);
      res.end(result.body);
    } catch (error) {
      const status = error.statusCode || 500;
      console.error(error);
      if (!res.headersSent) {
        res.writeHead(status, { 'content-type': 'text/plain; charset=utf-8' });
      }
      res.end(status === 413 ? 'Request too large.\n' : 'Something went wrong.\n');
    }
  });

  return new Promise((resolveListen, reject) => {
    server.once('error', reject);
    server.listen(port, host, () => {
      server.off('error', reject);
      const address = server.address();
      server.booksFile = file;
      console.log(`Books running at http://localhost:${address.port}`);
      console.log(`Saving books to ${file}`);
      resolveListen(server);
    });
  });
}

function readBody(req) {
  return new Promise((resolveBody, reject) => {
    if (req.method === 'GET' || req.method === 'HEAD') {
      resolveBody('');
      req.resume();
      return;
    }
    const chunks = [];
    let size = 0;
    req.on('data', (chunk) => {
      size += chunk.length;
      if (size > BODY_LIMIT) {
        const error = new Error('Body too large');
        error.statusCode = 413;
        reject(error);
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolveBody(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1]);
if (isMain) {
  startServer().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
"}

{"path":"/workspace/test/app.test.js","content":"import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, describe, expect, it } from 'vitest';
import { createApp } from '../src/app.js';
import { createStore } from '../src/store.js';
import { startServer } from '../server.js';

describe('book shelf', () => {
  let dir;
  let server;

  afterEach(async () => {
    if (server) {
      await new Promise((resolve) => server.close(resolve));
      server = undefined;
    }
    if (dir) {
      await rm(dir, { recursive: true, force: true });
      dir = undefined;
    }
  });

  it('shows reading and finished books, and keeps them after a restart', async () => {
    dir = await mkdtemp(join(tmpdir(), 'books-'));
    const dataFile = join(dir, 'books.json');
    server = await startServer({ port: 0, host: '127.0.0.1', dataFile });
    const base = baseUrl(server);

    const home = await fetch(`${base}/`);
    expect(home.status).toBe(200);
    const empty = await home.text();
    expect(section(empty, 'reading')).toContain('Nothing in progress.');
    expect(section(empty, 'finished')).toContain('No finished books yet.');

    const created = await fetch(`${base}/books`, {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        title: 'Piranesi',
        author: 'Susanna Clarke',
        notes: 'The halls.\nAgain.',
      }),
      redirect: 'manual',
    });
    expect(created.status).toBe(303);
    const location = created.headers.get('location');
    expect(location).toMatch(/^\/books\/[a-f0-9]+$/);

    const detailResponse = await fetch(`${base}${location}`);
    expect(detailResponse.status).toBe(200);
    const detail = await detailResponse.text();
    expect(detail).toContain('Piranesi');
    expect(detail).toContain('Susanna Clarke');
    expect(detail).toContain('The halls.\nAgain.');
    expect(detail).toContain(`${base}${location}`);
    expect(detail).toContain('Send this link to someone.');

    const reading = await (await fetch(`${base}/`)).text();
    expect(section(reading, 'reading')).toContain('Piranesi');
    expect(section(reading, 'finished')).not.toContain('Piranesi');

    const finish = await fetch(`${base}${location}/finish`, {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ next: '/' }),
      redirect: 'manual',
    });
    expect(finish.status).toBe(303);
    expect(finish.headers.get('location')).toBe('/');

    const after = await (await fetch(`${base}/`)).text();
    expect(section(after, 'reading')).not.toContain('Piranesi');
    expect(section(after, 'finished')).toContain('Piranesi');
    expect(section(after, 'finished')).toContain(location);

    const saved = JSON.parse(await readFile(dataFile, 'utf8'));
    expect(saved.books).toHaveLength(1);
    expect(saved.books[0]).toMatchObject({
      title: 'Piranesi',
      author: 'Susanna Clarke',
      notes: 'The halls.\nAgain.',
      status: 'finished',
    });
    expect(saved.books[0].finishedAt).toEqual(expect.any(String));

    await new Promise((resolve) => server.close(resolve));
    server = await startServer({ port: 0, host: '127.0.0.1', dataFile });
    const restarted = await (await fetch(`${baseUrl(server)}${location}`)).text();
    expect(restarted).toContain('Piranesi');
    expect(restarted).toContain('Susanna Clarke');
    expect(restarted).toContain('The halls.');
