import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

const EMPTY = { books: [] };

export function createStore(filePath) {
  let chain = Promise.resolve();

  async function read() {
    let raw;
    try {
      raw = await readFile(filePath, 'utf8');
    } catch (error) {
      if (error && error.code === 'ENOENT') return clone(EMPTY);
      throw error;
    }
    if (!raw.trim()) return clone(EMPTY);
    const data = JSON.parse(raw);
    if (!data || typeof data !== 'object' || !Array.isArray(data.books)) {
      throw new Error(`Invalid books file: ${filePath}`);
    }
    return data;
  }

  async function write(data) {
    await mkdir(dirname(filePath), { recursive: true });
    const tmp = `${filePath}.${process.pid}.tmp`;
    await writeFile(tmp, `${JSON.stringify(data, null, 2)}\n`, 'utf8');
    await rename(tmp, filePath);
  }

  function update(mutator) {
    const run = chain.then(async () => {
      const current = await read();
      const next = await mutator(current);
      if (!next || !Array.isArray(next.books)) {
        throw new Error('Store update must return a books array');
      }
      await write(next);
      return next;
    });
    chain = run.then(
      () => {},
      () => {},
    );
    return run;
  }

  return { filePath, read, update };
}

function clone(value) {
  return structuredClone(value);
}

import { randomBytes } from 'node:crypto';

const TITLE_MAX = 200;
const AUTHOR_MAX = 200;
const NOTES_MAX = 5000;

export function validateBookInput(input) {
  const title = String(input?.title ?? '').trim();
  const author = String(input?.author ?? '').trim();
  const notes = String(input?.notes ?? '').trim();
  const values = { title, author, notes };
  if (!title || !author) {
    return { error: 'Title and author are required.', values };
  }
  if (title.length > TITLE_MAX || author.length > AUTHOR_MAX) {
    return { error: 'Title and author must be 200 characters or fewer.', values };
  }
  if (notes.length > NOTES_MAX) {
    return { error: 'Notes must be 5000 characters or fewer.', values };
  }
  return { value: values, values };
}

export function addBook(data, input, now = new Date()) {
  const book = {
    id: uniqueId(data.books || []),
    title: input.title,
    author: input.author,
    notes: input.notes,
    status: 'reading',
    createdAt: now.toISOString(),
    finishedAt: null,
  };
  return { books: [book, ...(data.books || [])], book };
}

export function finishBook(data, id, now = new Date()) {
  const books = (data.books || []).map((book) => ({ ...book }));
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return null;
  if (books[index].status !== 'finished') {
    books[index] = {
      ...books[index],
      status: 'finished',
      finishedAt: now.toISOString(),
    };
  }
  return { books, book: books[index] };
}

export function findBook(data, id) {
  return (data.books || []).find((book) => book.id === id) || null;
}

export function splitBooks(data) {
  const books = data?.books || [];
  const reading = books
    .filter((book) => book && book.status !== 'finished')
    .sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')));
  const finished = books
    .filter((book) => book && book.status === 'finished')
    .sort((a, b) => String(b.finishedAt || '').localeCompare(String(a.finishedAt || '')));
  return { reading, finished };
}

export function isBookId(id) {
  return typeof id === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(id);
}

function uniqueId(books) {
  const used = new Set(books.map((book) => book.id));
  let id = '';
  do {
    id = randomBytes(4).toString('hex');
  } while (used.has(id));
  return id;
}

import { addBook, findBook, finishBook, isBookId, splitBooks, validateBookInput } from './books.js';
import { renderBook, renderHome, renderNotFound } from './render.js';

export function createApp(store) {
  return async function handle(request) {
    const url = new URL(request.url || '/', 'http://localhost');
    const path = normalizePath(url.pathname);
    const method = String(request.method || 'GET').toUpperCase();

    if (path === '/favicon.ico') return empty(204);

    if (path === '/') {
      if (method !== 'GET' && method !== 'HEAD') return text(405, 'Method not allowed');
      const data = await store.read();
      return html(200, renderHome(splitBooks(data)));
    }

    if (path === '/books') {
      if (method === 'GET' || method === 'HEAD') return redirect('/');
      if (method !== 'POST') return text(405, 'Method not allowed');
      const fields = parseForm(request.body);
      const parsed = validateBookInput(fields);
      if (parsed.error) {
        const data = await store.read();
        return html(400, renderHome({ ...splitBooks(data), error: parsed.error, values: parsed.values }));
      }
      let book;
      await store.update((data) => {
        const result = addBook(data, parsed.value);
        book = result.book;
        return { books: result.books };
      });
      return redirect(`/books/${book.id}`);
    }

    const finish = path.match(/^\/books\/([^/]+)\/finish$/);
    if (finish) {
      const id = decodeId(finish[1]);
      if (!id) return html(404, renderNotFound());
      if (method !== 'POST') return text(405, 'Method not allowed');
      const fields = parseForm(request.body);
      let found = false;
      await store.update((data) => {
        const result = finishBook(data, id);
        if (!result) return data;
        found = true;
        return { books: result.books };
      });
      if (!found) return html(404, renderNotFound());
      return redirect(safeNext(fields.next, id));
    }

    const detail = path.match(/^\/books\/([^/]+)$/);
    if (detail) {
      const id = decodeId(detail[1]);
      if (!id) return html(404, renderNotFound());
      if (method !== 'GET' && method !== 'HEAD') return text(405, 'Method not allowed');
      const book = findBook(await store.read(), id);
      if (!book) return html(404, renderNotFound());
      return html(200, renderBook(book, { shareUrl: absoluteUrl(request, `/books/${book.id}`) }));
    }

    return html(404, renderNotFound('Page not found'));
  };
}

function normalizePath(pathname) {
  const trimmed = pathname.replace(/\/+$/, '');
  return trimmed || '/';
}

function decodeId(raw) {
  try {
    const id = decodeURIComponent(raw);
    return isBookId(id) ? id : null;
  } catch {
    return null;
  }
}

function parseForm(body) {
  const params = new URLSearchParams(typeof body === 'string' ? body : '');
  return {
    title: params.get('title') ?? '',
    author: params.get('author') ?? '',
    notes: params.get('notes') ?? '',
    next: params.get('next') ?? '',
  };
}

function safeNext(value, id) {
  if (value === '/') return '/';
  if (value === `/books/${id}`) return value;
  return `/books/${id}`;
}

function absoluteUrl(request, path) {
  const headers = request.headers || {};
  const host = headers.host;
  if (!host || /[\s/]/.test(host)) return path;
  const forwarded = headers['x-forwarded-proto'];
  const proto = forwarded === 'https' ? 'https' : 'http';
  return `${proto}://${host}${path}`;
}

function html(status, body) {
  return {
    status,
    headers: {
      'content-type': 'text/html; charset=utf-8',
      'cache-control': 'no-store',
    },
    body,
  };
}

function text(status, body) {
  return {
    status,
    headers: { 'content-type': 'text/plain; charset=utf-8' },
    body,
  };
}

function redirect(location) {
  return {
    status: 303,
    headers: {
      location,
      'content-type': 'text/plain; charset=utf-8',
    },
    body: `Redirecting to ${location}\n`,
  };
}

function empty(status) {
  return { status, headers: {}, body: '' };
}

import { createServer } from 'node:http';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { createApp } from './src/app.js';
import { createStore } from './src/store.js';

const root = dirname(fileURLToPath(import.meta.url));
const BODY_LIMIT = 100_000;

export function startServer({ port = Number(process.env.PORT) || 3000, host = '0.0.0.0', dataFile } = {}) {
  const file = dataFile || (process.env.BOOKS_FILE ? resolve(process.env.BOOKS_FILE) : join(root, 'data', 'books.json'));
  const store = createStore(file);
  const app = createApp(store);
  const server = createServer(async (req, res) => {
    try {
      const body = await readBody(req);
      const result = await app({
        method: req.method,
        url: req.url,
        headers: req.headers,
        body,
      });
      res.writeHead(result.status, result.headers);
      res.end(result.body);
    } catch (error) {
      const status = error.statusCode || 500;
      console.error(error);
      if (!res.headersSent) {
        res.writeHead(status, { 'content-type': 'text/plain; charset=utf-8' });
      }
      res.end(status === 413 ? 'Request too large.\n' : 'Something went wrong.\n');
    }
  });

  return new Promise((resolveListen, reject) => {
    server.once('error', reject);
    server.listen(port, host, () => {
      server.off('error', reject);
      const address = server.address();
      server.booksFile = file;
      console.log(`Books running at http://localhost:${address.port}`);
      console.log(`Saving books to ${file}`);
      resolveListen(server);
    });
  });
}

function readBody(req) {
  return new Promise((resolveBody, reject) => {
    if (req.method === 'GET' || req.method === 'HEAD') {
      resolveBody('');
      req.resume();
      return;
    }
    const chunks = [];
    let size = 0;
    req.on('data', (chunk) => {
      size += chunk.length;
      if (size > BODY_LIMIT) {
        const error = new Error('Body too large');
        error.statusCode = 413;
        reject(error);
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolveBody(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1]);
if (isMain) {
  startServer().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}

